import {createFirebaseSession} from './firebase-session.mjs';
import {recipeNutrition} from './indian.mjs';
import {personalCatalog,matchesFood} from './personal.mjs';
import {keys,scale,totals,localDate,weightTrend,averageWeight} from './core.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({version:1,days:{},customFoods:[],recipes:[],profile:{name:'Nikhil',diet:'vegetarian',goal:'Build strength & lose fat',targets:{kcal:2100,protein:95,fat:65,carbs:250,fiber:30,sleep:8,exercise:30}},revision:0,pending:true});
let state;try{state=JSON.parse(localStorage.getItem('sprout-v1'))||blank();}catch{state=blank();}
let authSession=null,authLoad=null;
let syncing=false,syncTimer,personal={favorites:[],extras:[],combos:[]},tray=[],trayMeal="Breakfast",foodLimit=18;
let foods=[],tab='today',date=localDate(),search='',filter=state.profile.diet,cloudUser=null,recipeDraft=[],recipeMeta={},storageAvailable=true;
const names={kcal:'Calories',protein:'Protein',fat:'Fat',carbs:'Carbs',fiber:'Fiber'};
const colors={protein:'#9bc779',fat:'#eac06a',carbs:'#94b2d6',fiber:'#c0a3d6',kcal:'#91ad68'};
const day=()=>state.days[date]||{meals:[],weight:null,sleep:null,exercise:[]};
const exerciseMinutes=d=>(d.exercise||[]).reduce((s,e)=>s+e.minutes,0);
const n=v=>Number(v||0).toLocaleString(undefined,{maximumFractionDigits:1});
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function persist(){state.pending=true;state.eventId=crypto.randomUUID();try{localStorage.setItem('sprout-v1',JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;notify('Device storage is unavailable. Export JSON to keep your entries.');}updateStatus();if(cloudUser){clearTimeout(syncTimer);syncTimer=setTimeout(sync,1200);}}
function updateStatus(){$('#save-status').textContent=!storageAvailable?'Not saved — export JSON':state.pending?'Saved here · cloud pending':'Cloud synced';}
function editDay(fn){const d=structuredClone(day());fn(d);state.days[date]=d;persist();render();}
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}
function close(){$('#modal').close();}
$('.close').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close();});
$('#day').value=date;$('#day').max=localDate();$('#day').onchange=e=>{if(e.target.value&&e.target.value<=localDate()){date=e.target.value;render();}};
function navigate(t){tab=t;render();}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));$('#profile-button').onclick=()=>navigate('settings');
function render(){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#date-label').textContent=new Date(date+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'}).toUpperCase();$('#page-title').innerHTML=({today:'Make today count',food:'What sounds good?',progress:'Look how far you’ve come',settings:'Make it yours',training:'Your next stronger self'}[tab])+'<span>.</span>';$('#profile-button').textContent=state.profile.name.slice(0,1);({today:renderToday,food:renderFood,progress:renderProgress,settings:renderSettings,training:renderTraining}[tab])();updateStatus();attachDepth();}
function renderToday(){const d=day(),t=totals(d.meals),g=state.profile.targets,min=exerciseMinutes(d),trend=weightTrend(state.days,date);const quests=[{done:d.meals.length>0,title:'Fuel your day',detail:'Log a meal, however simple.',action:'food'},{done:d.weight!=null,title:'Check in with yourself',detail:'A weight entry is a data point, not a verdict.',action:'weight'},{done:min>=g.exercise,title:'Find your kind of movement',detail:`${n(min)} / ${g.exercise} minutes logged`,action:'exercise'}];const count=quests.filter(q=>q.done).length;
$('#content').innerHTML=`<div class="top-grid"><section class="journey mission-scene" id="mission-scene"><div class="journey-copy"><span class="pill">YOUR 12-WEEK CHAPTER</span><h2>Build strength.<br>Find your rhythm.</h2><p>Resistance bands. Familiar food.<br>A little more you, every week.</p><button class="primary" id="log-meal">+ Fuel up</button><button class="text-button" id="open-training">Open training</button></div><div class="avatar-space"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><button class="identity-core personal-avatar" id="avatar-info" aria-label="Open your personal avatar"><img src="assets/nikhil-avatar.png" alt="Your stylized 3D cartoon avatar"></button><span class="orbit-data protein-orbit">${n(t.protein)}<small>g protein</small></span><span class="orbit-data movement-orbit">${min}<small>min moved</small></span></div><span class="scene-caption">Move your pointer to explore · touch-friendly controls below</span></section><section class="card"><div class="card-head"><h2>Daily energy</h2><small>kcal</small></div><div class="energy-body"><div class="ring" style="--angle:${Math.min(360,t.kcal/g.kcal*360)}deg"><div class="ring-text"><strong>${n(t.kcal)}</strong><small>of ${n(g.kcal)} kcal</small></div></div><div class="energy-details"><p>${t.kcal>g.kcal?'ABOVE TARGET':'REMAINING'}</p><b>${n(Math.abs(g.kcal-t.kcal))} <small>kcal</small></b><hr><p>MEALS LOGGED</p><b>${d.meals.length}</b></div></div><p class="hint">${t.missing.includes('kcal')?'Some foods are missing energy values. Total is partial.':(d.meals.some(m=>m.food?.estimated)?'Includes your earlier recipe estimates.':'Your editable target · exercise calories are not deducted.')}</p></section></div><div class="section-heading"><h2>Your daily essentials</h2><button class="text-button" id="edit-targets">Edit targets</button></div><div class="macros">${['protein','carbs','fat','fiber'].map(k=>`<div class="macro"><div class="macro-top"><span>${names[k]}</span><span style="color:${colors[k]}">◈</span></div><strong>${n(t[k])}<small> g</small></strong> <small>/ ${g[k]} g${t.missing.includes(k)?' · partial':''}</small><div class="bar"><span style="width:${Math.min(100,t[k]/g[k]*100)}%;--color:${colors[k]}"></span></div></div>`).join('')}<div class="macro"><div class="macro-top"><span>Movement</span><span>↗</span></div><strong>${n(min)}<small> min</small></strong> <small>/ ${g.exercise}</small><div class="bar"><span style="width:${Math.min(100,min/g.exercise*100)}%"></span></div></div></div><div class="checkins"><button class="checkin" data-check="weight"><span>◉ &nbsp; BODY WEIGHT</span><strong>${d.weight==null?'Add weight':n(d.weight)+' kg'}</strong><small>${trend&&trend.to===date?`${Math.abs(trend.delta)<0.05?'Steady':trend.delta>0?'↑ Gained':'↓ Lost'} ${n(Math.abs(trend.delta))} kg since ${trend.from}`:'Build your personal baseline'} · +</small></button><button class="checkin" data-check="sleep"><span>☾ &nbsp; LAST NIGHT’S SLEEP</span><strong>${d.sleep==null?'Log sleep':n(d.sleep)+' hours'}</strong><small>Your target: ${g.sleep} hours · +</small></button><button class="checkin" data-check="exercise"><span>↗ &nbsp; EXERCISE</span><strong>${min?min+' minutes':'Add movement'}</strong><small>Every kind of movement counts · +</small></button></div><div class="lower-grid"><section class="card"><div class="card-head"><h2>On your plate</h2><button class="text-button" id="add-food">+ Add food</button></div>${d.meals.length?d.meals.map((m,i)=>`<div class="meal-row"><span class="meal-icon">◈</span><div class="meal-info"><b>${esc(m.name)}</b><small>${esc(m.meal)} · ${n(m.grams)} g · ${m.nutrients.protein==null?"—":n(m.nutrients.protein)} g protein</small></div><span class="meal-kcal">${m.nutrients.kcal==null?'—':n(m.nutrients.kcal)}</span><button class="text-button" data-edit="${i}" aria-label="Edit ${esc(m.name)}">Edit</button><button class="text-button danger" data-delete="${i}" aria-label="Delete ${esc(m.name)}">×</button></div>`).join(''):`<div class="meal-empty"><div class="empty-symbol">◈</div><h3>A fresh plate. A fresh start.</h3><p>Find your food, dial in the portion,<br>and let the numbers take care of themselves.</p><button class="secondary" id="browse-food">Explore food studio</button></div>`}</section><section class="card"><div class="card-head"><h2>Today’s little wins</h2><span class="tag">${count}/3 complete</span></div>${quests.map(q=>`<div class="quest ${q.done?'complete':''}"><span class="quest-icon">${q.done?'✓':'○'}</span><div><b>${q.title}</b><p>${q.detail}</p></div><button class="text-button" data-quest="${q.action}">${q.done?'Edit':'Start'}</button></div>`).join('')}</section></div><div class="insight"><span>✦</span><div><b>A thought for today</b><p>${suggestion(d,t)}</p></div></div><footer>Energy and protein targets come from your previous Fuel Log. They remain editable; they are not a newly calculated prescription.</footer>`;
['#log-meal','#add-food','#browse-food'].forEach(s=>{if($(s))$(s).onclick=()=>navigate('food');});$('#open-training').onclick=()=>navigate('training');$('#avatar-info').onclick=()=>modal('<h2>Your next stronger self</h2><img class="avatar-preview" src="assets/nikhil-avatar.png" alt="Your personal avatar"><p>A simplified 3D character inspired by your selected photos. Every meal and movement you log updates your dashboard.</p>');$('#edit-targets').onclick=()=>navigate('settings');document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>checkin(b.dataset.check));document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>b.dataset.quest==='food'?navigate('food'):checkin(b.dataset.quest));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('Remove this food from this day?'))editDay(d=>d.meals.splice(Number(b.dataset.delete),1));});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>portion(day().meals[Number(b.dataset.edit)].food,Number(b.dataset.edit)));}
function suggestion(d,t){if(!d.meals.length)return 'Start by logging what you normally eat. A useful pattern begins with an honest picture of your day.';if(t.missing.length)return 'Some foods have missing nutrient values. Check their labels before drawing conclusions from today’s totals.';if(t.protein<state.profile.targets.protein*.6)return 'Your logged protein is below your chosen target so far. Explore lentils, tofu, beans or plain Greek yogurt for your next meal.';if(d.sleep==null)return 'Add last night’s sleep to put your food and activity in context. Look for patterns across weeks, not one day.';return 'You’re building a useful record. Compare weekly averages and how you feel before changing your routine.';}
function checkin(type){if(type==='exercise'){modal(`<h2>Move in your own way</h2><p>Log what you did. Apple Health is not connected.</p><form id="check-form"><label class="field">Activity<select name="activity"><option>Strength training</option><option>Walking</option><option>Running</option><option>Cycling</option><option>Yoga</option><option>Swimming</option><option>Other exercise</option></select></label><label class="field">Minutes<input name="value" type="number" min="1" max="1440" required></label><button class="primary">Save activity</button></form>${day().exercise.map((e,i)=>`<div class="meal-row"><div class="meal-info">${esc(e.name)} · ${e.minutes} min</div><button class="text-button danger" data-remove-ex="${i}">Remove</button></div>`).join('')}`);document.querySelectorAll('[data-remove-ex]').forEach(b=>b.onclick=()=>{editDay(d=>d.exercise.splice(+b.dataset.removeEx,1));close();checkin(type);});}else{modal(`<h2>${type==='weight'?'Your daily check-in':'Rest is part of the work'}</h2><p>${type==='weight'?'A single reading can fluctuate. Your longer trend matters.':'Sleep duration for the night ending on the selected day.'}</p><form id="check-form"><label class="field">${type==='weight'?'Weight (kg)':'Sleep (hours)'}<input name="value" type="number" step="0.1" min="${type==='weight'?20:0}" max="${type==='weight'?400:24}" value="${day()[type]??''}" required></label><button class="primary">Save check-in</button></form>`);}$('#check-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),v=Number(f.get('value'));editDay(d=>{if(type==='exercise')d.exercise.push({id:crypto.randomUUID(),name:f.get('activity'),minutes:v,source:'manual'});else d[type]=v;});close();notify('One small win, saved.');};}
function allFoods(){return [...state.customFoods,...state.recipes,...personal.extras,...foods];}
function foodVisual(f){return f.image?`<img src="${esc(f.image)}" alt="${esc(f.displayName||f.name)}" loading="lazy">`:`<span class="food-symbol" aria-hidden="true">${f.emoji||(/rice/i.test(f.name)?'🍚':/milk|yogurt|cheese/i.test(f.name)?'🥛':/banana|fruit/i.test(f.name)?'🍌':/lentil|bean|chickpea/i.test(f.name)?'🫘':'◈')}</span>`;}
function renderFood(){const searching=search.trim().length>0;const catalog=[...personal.favorites,...state.customFoods,...state.recipes,...allFoods()];const seen=new Set();const unique=catalog.filter(f=>{if(!f.id||seen.has(f.id))return false;seen.add(f.id);return true;});const matches=unique.filter(f=>(filter==='all'||filter==='vegetarian'&&['plant','dairy'].includes(f.diet)||f.diet===filter||filter==='custom'&&String(f.id).startsWith('custom'))&&matchesFood(f,search));const shown=searching?matches.slice(0,foodLimit):filter==='vegetarian'?personal.favorites:matches.slice(0,foodLimit);
$('#content').innerHTML=`<div class="food-workspace"><div class="food-shelf"><div class="search-dock"><span>⌕</span><input type="search" id="search" autocomplete="off" placeholder="Try “Chobani yogurt” or “rice”…" value="${esc(search)}" aria-label="Search foods"><button class="text-button" id="custom">+ Custom</button></div><div class="filter-chips" role="group" aria-label="Food filters">${[['vegetarian','Your vegetarian shelf'],['plant','Plant foods'],['all','All foods'],['custom','Your creations']].map(([v,l])=>`<button class="${filter===v?'selected':''}" data-filter="${v}">${l}</button>`).join('')}</div>${!searching&&filter==='vegetarian'?`<div class="section-heading"><div><span class="eyebrow">LESS TAPPING. MORE LIVING.</span><h2>Your go-to combinations</h2></div><button class="text-button" id="recipe">Build a recipe</button></div><div class="combo-row">${personal.combos.map(c=>`<button class="combo-card" data-combo="${c.id}">${foodVisual(c)}<span class="combo-shade"></span><span class="combo-copy"><small>${c.estimated?'INCLUDES ESTIMATES':'INGREDIENT-BASED'}</small><b>${c.name}</b><span>${c.description}</span></span><span class="combo-add">+</span></button>`).join('')}</div>`:''}<div class="section-heading"><h2>${searching?'Find your exact match':'The familiar favorites'}</h2><span class="muted">${searching?matches.length+' matches':'Tap to explore a portion'}</span></div><div class="visual-food-grid">${shown.map(f=>{const grams=f.defaultGrams||100,t=scale(f.nutrients,grams);return `<article class="visual-food-card"><button class="food-front" data-explore="${esc(f.id)}">${foodVisual(f)}<span class="food-badge">${f.estimated?'ESTIMATE':f.id.startsWith('brand-')?'PRODUCT LABEL':'FOOD RECORD'}</span></button><div class="food-card-copy"><h3>${esc(f.displayName||f.name)}</h3><p>${n(grams)+' g'} · ${t.kcal==null?'—':n(t.kcal)} kcal</p><div class="food-card-bottom"><span><b>${t.protein==null?'—':n(t.protein)}g</b> protein</span><button class="round-add" data-tray="${esc(f.id)}" aria-label="Add ${esc(f.displayName||f.name)} to meal tray">+</button></div></div></article>`;}).join('')}</div>${!shown.length?'<div class="card meal-empty"><h3>Let’s add your version.</h3><p>No matching product yet. Use “Custom” to enter its label. Brands and flavors aren’t interchangeable.</p></div>':''}${searching&&matches.length>foodLimit?'<button class="secondary full" id="more-foods">Show more matches</button>':''}<footer>Product photos identify exact items. Meal photos are illustrative. Recipe photos are AI illustrations. Modeled dishes are estimates; customize ingredients to match your cooking. Tap a card to inspect its source. <a href="https://fdc.nal.usda.gov/download-datasets/" target="_blank" rel="noopener">USDA library</a></footer></div><aside class="meal-tray" id="meal-tray"></aside></div>`;
$('#search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;foodLimit=18;renderFood();$('#search').focus();$('#search').setSelectionRange(pos,pos);};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderFood();});$('#custom').onclick=customFood;if($('#recipe'))$('#recipe').onclick=()=>recipeBuilder();if($('#more-foods'))$('#more-foods').onclick=()=>{foodLimit+=18;renderFood();};const find=id=>unique.find(f=>String(f.id)===id);document.querySelectorAll('[data-tray]').forEach(b=>b.onclick=()=>{const f=find(b.dataset.tray);tray.push({food:structuredClone(f),grams:f.defaultGrams||100});renderTray();notify('Added to your meal tray. Review, then log.');});document.querySelectorAll('[data-explore]').forEach(b=>b.onclick=()=>portion(find(b.dataset.explore)));document.querySelectorAll('[data-combo]').forEach(b=>b.onclick=()=>{const combo=personal.combos.find(c=>c.id===b.dataset.combo);for(const [id,grams]of combo.items){const f=find(id);if(f)tray.push({food:structuredClone(f),grams});}renderTray();notify('Combination added. Adjust each portion before logging.');});renderTray();attachDepth();}
function renderTray(){if(!$('#meal-tray'))return;const t=totals(tray.filter(x=>Number.isFinite(x.grams)&&x.grams>0&&x.grams<=10000).map(x=>({nutrients:scale(x.food.nutrients,x.grams)})));$('#meal-tray').innerHTML=`<div class="tray-head"><span class="eyebrow">MEAL IN THE MAKING</span><h2>Your plate<span>.</span></h2><p>${tray.length?'Looking good. Make it your portion.':'Build a meal from your favorites.'}</p></div><div class="tray-orbit"><strong id="tray-energy">${n(t.kcal)}${t.missing.includes('kcal')?'*':''}</strong><small>kcal in this meal</small></div>${tray.length?`<div class="tray-items">${tray.map((x,i)=>`<div class="tray-item"><div class="tray-thumb">${foodVisual(x.food)}</div><div><b>${esc(x.food.displayName||x.food.name)}</b><label><input type="number" required min=".1" max="10000" step=".1" value="${Number.isFinite(x.grams)?x.grams:''}" data-grams="${i}" aria-label="Grams of ${esc(x.food.name)}"> g ${x.food.estimated?'· estimate':''}</label></div><button data-remove-tray="${i}" aria-label="Remove ${esc(x.food.name)}">×</button></div>`).join('')}</div>`:'<div class="tray-empty">Tap + on a food<br>or choose a combination.</div>'}<div class="tray-macros">${['protein','carbs','fat','fiber'].map(k=>`<div><b data-tray-total="${k}">${n(t[k])}g${t.missing.includes(k)?'*':''}</b><small>${names[k]}</small></div>`).join('')}</div><label class="field">Add to<select id="tray-meal"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select></label><button class="primary full" id="log-tray" ${tray.length?'':'disabled'}>Log this meal · ${date}</button><p class="hint">${tray.some(x=>x.food.estimated)?'Includes recipe estimates. ':''}Nothing is logged until you tap this button.${t.missing.length?' * Partial totals.':''}</p>`;
updateTrayTotals();$('#tray-meal').value=trayMeal;$('#tray-meal').onchange=e=>{trayMeal=e.target.value;};document.querySelectorAll('[data-grams]').forEach(input=>input.oninput=e=>{tray[+e.target.dataset.grams].grams=e.target.valueAsNumber;updateTrayTotals();});document.querySelectorAll('[data-remove-tray]').forEach(b=>b.onclick=()=>{tray.splice(+b.dataset.removeTray,1);renderTray();});$('#log-tray').onclick=()=>{const invalid=$('#meal-tray input:invalid');if(invalid){invalid.reportValidity();return;}const meal=$('#tray-meal').value;editDay(d=>{for(const x of tray)d.meals.push({id:crypto.randomUUID(),foodId:x.food.id,name:x.food.displayName||x.food.name,grams:x.grams,meal,nutrients:scale(x.food.nutrients,x.grams),food:structuredClone(x.food)});});tray=[];renderFood();notify('Meal logged. Daily nutrition updated.');};}

function updateTrayTotals(){
 const valid=tray.length>0&&tray.every(x=>Number.isFinite(x.grams)&&x.grams>0&&x.grams<=10000)&&!$('#meal-tray input:invalid');
 $('#log-tray').disabled=!valid;
 const t=valid?totals(tray.map(x=>({nutrients:scale(x.food.nutrients,x.grams)}))):null;
 $('#tray-energy').textContent=t?n(t.kcal)+(t.missing.includes('kcal')?'*':''):'—';
 document.querySelectorAll('[data-tray-total]').forEach(el=>{const k=el.dataset.trayTotal;el.textContent=t?n(t[k])+'g'+(t.missing.includes(k)?'*':''):'—';});
}
function portion(food,index=null){const existing=index==null?null:day().meals[index];let grams=existing?.grams||food.defaultGrams||100;modal(`<span class="tag">${esc(food.source)}</span>${food.image?`<img class="portion-photo" src="${esc(food.image)}" alt="${esc(food.displayName||food.name)}">`:""}<h2>${esc(food.displayName||food.name)}</h2><p>${esc(food.note||"Choose the matching preparation and weigh your portion.")}</p>${food.ingredients?'<button class="secondary full" id="customize-recipe">Customize recipe · ingredients & oil</button>':''}<form id="portion-form"><label class="field">Serving size<select id="serving"><option value="">Custom grams</option><option value="100">100 g</option>${(food.portions||[]).map(p=>`<option value="${p.grams}">${esc(p.label)} (${n(p.grams)} g)</option>`).join('')}</select></label><label class="field">Quantity (grams)<div class="quantity"><button type="button" id="minus" aria-label="Reduce portion">−</button><input id="grams" type="number" min="0.1" max="10000" step="0.1" required value="${grams}"><button type="button" id="plus" aria-label="Increase portion">+</button></div></label><input id="quantity-range" aria-label="Adjust portion in grams" type="range" min="5" max="500" step="5" value="${grams}"><div class="nutrition-preview" id="nutrition-preview"></div><label class="field">Meal<select id="meal"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select></label><p class="hint">${food.sourceUrl?`<a href="${esc(food.sourceUrl)}" target="_blank" rel="noopener">View original nutrient record</a>`:'User-entered or recipe-calculated nutrition.'} · Values scale from 100 g. Missing values stay unknown.</p><button class="primary">${index==null?'Add to my day':'Save portion'}</button>${index==null?'<button type="button" id="add-ingredient" class="text-button full">Add to recipe instead</button>':''}</form>`);if($('#customize-recipe'))$('#customize-recipe').onclick=()=>recipeBuilder(food);if(existing)$('#meal').value=existing.meal;const preview=()=>{grams=Number($('#grams').value);if(!Number.isFinite(grams)||grams<=0||grams>10000){$('#nutrition-preview').textContent='Enter a valid portion to calculate nutrition.';return;}const t=scale(food.nutrients,grams);$('#nutrition-preview').innerHTML=keys.map(k=>`<span><b>${t[k]==null?'—':n(t[k])}${k==='kcal'?'':' g'}</b>${names[k]}</span>`).join('');$('#quantity-range').value=grams;$('#serving').value=String(grams);if(!$('#serving').value)$('#serving').value='';};$('#grams').oninput=preview;$('#quantity-range').oninput=e=>{$('#grams').value=e.target.value;preview();};$('#serving').value=String(grams);if(!$('#serving').value)$('#serving').value='';$('#serving').onchange=e=>{if(e.target.value){$('#grams').value=e.target.value;preview();}};$('#minus').onclick=()=>{$('#grams').value=Math.max(.1,grams-10);preview();};$('#plus').onclick=()=>{$('#grams').value=Math.min(10000,grams+10);preview();};preview();$('#portion-form').onsubmit=e=>{e.preventDefault();const entry={id:existing?.id||crypto.randomUUID(),foodId:food.id,name:food.name,grams,meal:$('#meal').value,nutrients:scale(food.nutrients,grams),food:structuredClone(food)};editDay(d=>{if(index==null)d.meals.push(entry);else d.meals[index]=entry;});close();notify('Meal saved. Your daily totals are updated.');};if($('#add-ingredient'))$('#add-ingredient').onclick=()=>{if(!$('#portion-form').reportValidity())return;recipeDraft.push({food,grams});close();recipeBuilder();};}
function customFood(){modal(`<h2>A place for your favorites</h2><p>Copy the nutrition label. Enter values per 100 g; leave unknown nutrients blank.</p><form id="custom-form" class="form-grid"><label class="field wide">Food name<input name="name" required maxlength="180"></label><label class="field wide">Diet<select name="diet"><option value="dairy">Vegetarian with dairy</option><option value="plant">Plant-based</option><option value="other">Other / unknown</option></select></label>${keys.map(k=>`<label class="field">${names[k]} ${k==='kcal'?'(kcal)':'(g)'}<input type="number" name="${k}" min="0" max="${k==='kcal'?1000:100}" step="0.01"></label>`).join('')}<label class="field wide">Label / source note<input name="note" maxlength="300" placeholder="Brand and product, package label"></label><button class="primary wide">Save custom food</button></form>`);$('#custom-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),food={id:'custom-'+crypto.randomUUID(),name:f.get('name').trim(),diet:f.get('diet'),source:'Your nutrition label',sourceNote:f.get('note'),basisGrams:100,portions:[],nutrients:Object.fromEntries(keys.map(k=>[k,f.get(k)===''?null:Number(f.get(k))]))};if(!food.name)return;state.customFoods.push(food);persist();close();renderFood();portion(food);};}
function recipeBuilder(template){
 if(template){recipeDraft=structuredClone(template.ingredients);recipeMeta={name:'My '+(template.displayName||template.name),weight:template.batchGrams||template.portions?.find(p=>p.label==='Full batch')?.grams||500,image:template.image};}
 const remember=()=>{recipeMeta.name=$('#recipe-name').value;recipeMeta.weight=$('#recipe-weight').value;};
 modal(`<h2>Your recipe, your portions</h2><p>Adjust the ingredients actually used. Include cooking fat once. Enter the weight of the whole cooked batch, including its water.</p><form id="recipe-form">${recipeDraft.map((x,i)=>`<div class="recipe-ingredient"><div class="tray-thumb">${foodVisual(x.food)}</div><label class="field">${esc(x.food.displayName||x.food.name)}${x.food.sourceUrl?`<a class="ingredient-source" href="${esc(x.food.sourceUrl)}" target="_blank" rel="noopener">Nutrient source ↗</a>`:''}<input data-recipe-grams="${i}" type="number" min="0.1" max="10000" step="0.1" required value="${x.grams}" aria-label="Ingredient grams: ${esc(x.food.name)}"></label><span>g</span><button type="button" class="text-button" data-remove-ingredient="${i}" aria-label="Remove ${esc(x.food.name)}">×</button></div>`).join('')}<div class="fat-shortcuts">${[['172336','+ Oil'],['173410','+ Butter'],['173412','+ Ghee']].map(([id,label])=>`<button type="button" class="secondary" data-recipe-fat="${id}">${label} · 5 g</button>`).join('')}</div><button type="button" class="text-button full" id="find-ingredient">+ Find another ingredient</button><label class="field">Recipe name<input id="recipe-name" required maxlength="180" value="${esc(recipeMeta.name||'')}" placeholder="My dal, chana, overnight oats…"></label><label class="field">Finished batch weight (g)<input id="recipe-weight" required type="number" min="1" max="20000" step="0.1" value="${esc(recipeMeta.weight||'')}"></label><p class="hint">Nutrition per 100 g of your finished recipe</p><div class="nutrition-preview" id="recipe-preview" aria-live="polite"></div><button class="primary" id="save-recipe">Save recipe & choose portion</button></form>`);
 const preview=()=>{remember();try{const nutrients=recipeNutrition(recipeDraft,Number(recipeMeta.weight));$('#recipe-preview').innerHTML=keys.map(k=>`<span><b>${nutrients[k]==null?'—':n(nutrients[k])}${k==='kcal'?'':' g'}</b>${names[k]}</span>`).join('');$('#save-recipe').disabled=false;}catch{$('#recipe-preview').textContent='Add ingredients and valid weights to calculate your recipe.';$('#save-recipe').disabled=true;}};
 document.querySelectorAll('[data-recipe-grams]').forEach(el=>el.oninput=()=>{recipeDraft[+el.dataset.recipeGrams].grams=el.valueAsNumber;preview();});
 $('#recipe-weight').oninput=preview;$('#recipe-name').oninput=remember;
 document.querySelectorAll('[data-remove-ingredient]').forEach(b=>b.onclick=()=>{remember();recipeDraft.splice(+b.dataset.removeIngredient,1);recipeBuilder();});
 document.querySelectorAll('[data-recipe-fat]').forEach(b=>b.onclick=()=>{remember();const food=allFoods().find(f=>f.id===b.dataset.recipeFat);const item=recipeDraft.find(x=>x.food.id===food.id);if(item)item.grams=(Number.isFinite(item.grams)?item.grams:0)+5;else recipeDraft.push({food:structuredClone(food),grams:5});recipeBuilder();});
 $('#find-ingredient').onclick=()=>{remember();close();navigate('food');notify('Tap a food, then choose “Add to recipe instead”.');};
 $('#recipe-form').onsubmit=e=>{e.preventDefault();remember();const weight=Number(recipeMeta.weight),food={id:'custom-recipe-'+crypto.randomUUID(),name:recipeMeta.name.trim(),source:'Your recipe · calculated',diet:recipeDraft.some(x=>x.food.diet==='other')?'other':recipeDraft.some(x=>x.food.diet==='dairy')?'dairy':'plant',basisGrams:100,batchGrams:weight,defaultGrams:100,image:recipeMeta.image,portions:[{label:'Full batch',grams:weight}],ingredients:structuredClone(recipeDraft),nutrients:recipeNutrition(recipeDraft,weight),note:'Calculated from your ingredient quantities and final cooked batch weight. Includes the fats listed in your recipe.'};if(!food.name)return;state.recipes.push(food);recipeDraft=[];recipeMeta={};persist();close();renderFood();portion(food);};preview();
}
function renderProgress(){const rows=Object.entries(state.days).filter(([d])=>d<=date).sort(([a],[b])=>a.localeCompare(b));const weights=rows.filter(([,d])=>d.weight!=null).slice(-30),trend=weightTrend(state.days,date);const end=new Date(date+'T12:00:00'),start=new Date(end);start.setDate(start.getDate()-6);const prevEnd=new Date(start);prevEnd.setDate(prevEnd.getDate()-1);const prevStart=new Date(prevEnd);prevStart.setDate(prevStart.getDate()-6);const avg=averageWeight(state.days,localDate(start),date),prev=averageWeight(state.days,localDate(prevStart),localDate(prevEnd));let chart='<div class="meal-empty"><h3>Your story starts with a check-in.</h3><p>Log at least two weights to see a trend.</p></div>';if(weights.length>=2){const values=weights.map(([,d])=>d.weight),lo=Math.min(...values)-.5,hi=Math.max(...values)+.5;const first=new Date(weights[0][0]).getTime(),last=new Date(weights.at(-1)[0]).getTime();const points=weights.map(([d,v])=>`${20+(new Date(d).getTime()-first)/(last-first)*660},${190-(v.weight-lo)/(hi-lo)*160}`).join(' ');chart=`<svg class="chart" viewBox="0 0 700 220" role="img" aria-label="Body weight by date"><path d="M20 50H680M20 120H680M20 190H680" stroke="#e7ebe5"/><polyline points="${points}" fill="none" stroke="#7da64c" stroke-width="3" stroke-linejoin="round"/>${points.split(' ').map(p=>{const [x,y]=p.split(',');return `<circle cx="${x}" cy="${y}" r="5" fill="#bceb78" stroke="#547b30"/>`;}).join('')}</svg><div class="chart-labels"><span>${weights[0][0]} · ${n(values[0])} kg</span><span>${weights.at(-1)[0]} · ${n(values.at(-1))} kg</span></div>`;}
$('#content').innerHTML=`<div class="top-grid"><section class="card"><div class="card-head"><h2>The bigger picture</h2><span class="tag">Last 30 weigh-ins</span></div>${chart}</section><section class="card"><span class="eyebrow">7-DAY AVERAGE</span><div class="big-number">${avg.value==null?'—':n(avg.value)+' kg'}</div><p class="muted">${avg.count} readings in the selected week</p><p>${avg.count>=3&&prev.count>=3?`${n(avg.value-prev.value)} kg compared with the previous week`:'Log at least 3 weights in each week for a weekly comparison.'}</p><div class="insight"><div><b>Progress has more than one number.</b><p>Use trends alongside strength, energy, sleep and how you feel. Daily scale changes don’t tell the whole story.</p></div></div></section></div><div class="section-heading"><h2>Your daily record</h2><button class="text-button" id="export-progress">Export JSON</button></div><div class="card table-wrap"><table><thead><tr><th>Date</th><th>Weight</th><th>Calories</th><th>Protein</th><th>Fat</th><th>Carbs</th><th>Fiber</th><th>Sleep</th><th>Exercise</th></tr></thead><tbody>${rows.slice().reverse().map(([dt,d])=>{const t=totals(d.meals);return `<tr><td>${dt}</td><td>${d.weight==null?'—':n(d.weight)+' kg'}</td>${keys.map(k=>`<td>${d.meals.length?n(t[k])+(t.missing.includes(k)?'*':''):'—'}</td>`).join('')}<td>${d.sleep??'—'} h</td><td>${exerciseMinutes(d)} min</td></tr>`;}).join('')||'<tr><td colspan="9">No entries yet. Your first day is waiting.</td></tr>'}</tbody></table></div><footer>Blank days are not counted as zero. * Partial nutrient total. Nutrition data alone cannot establish why your weight changed.</footer>`;$('#export-progress').onclick=exportData;}
function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),schemaVersion:1,...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`sprout-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderSettings(){$('#content').innerHTML=`<div class="settings-grid"><section class="card"><h2>A plan that feels like you</h2><p>Your earlier Fuel Log used 2,100 kcal and 95 g protein. These remain editable; other targets are starting points, not a personalized prescription.</p><form id="settings-form"><div class="form-grid"><label class="field">Your name<input name="name" value="${esc(state.profile.name)}" required maxlength="60"></label><label class="field">Focus<select name="goal"><option>Build strength & lose fat</option><option>Build strength</option><option>Gradual weight loss</option><option>Maintain & feel good</option></select></label>${Object.entries(state.profile.targets).map(([k,v])=>`<label class="field">${names[k]||({sleep:'Sleep (hours)',exercise:'Exercise (minutes)'}[k])}${['protein','fat','carbs','fiber'].includes(k)?' (g)':''}<input name="${k}" type="number" min="${k==='sleep'?1:1}" max="${k==='kcal'?10000:k==='sleep'?24:k==='exercise'?1440:1000}" step="${k==='sleep'?'.1':'1'}" required value="${v}"></label>`).join('')}</div><button class="primary">Save my goals</button></form></section><div><section class="card"><h2>Your data, in your hands</h2><p id="connection-copy">${window.SPROUT_CONFIG?.apiUrl?'Cloud endpoint configured. Sign in to sync.':'Google Cloud is not connected yet. Entries are stored on this device until you connect your new project.'}</p><div id="google-signin"></div><div class="toolbar"><button class="secondary" id="sync" ${cloudUser&&window.SPROUT_CONFIG?.apiUrl?'':'disabled'}>Sync to BigQuery</button><button class="text-button" id="restore" ${cloudUser&&window.SPROUT_CONFIG?.apiUrl?'':'disabled'}>Restore cloud copy</button>${cloudUser?'<button class="text-button" id="signout">Sign out</button>':''}</div><button class="secondary" id="export">Export my JSON</button><p class="hint">Cloud sign-in and storage will be restricted to your account. Export a backup before clearing browser data.</p></section><section class="card" style="margin-top:22px"><h2>Apple Health</h2><p>Manual exercise logging is ready. Direct Apple Health access requires an iPhone app or a separately configured bridge, so automatic sync is not connected.</p><button class="secondary" id="manual-exercise">Log an activity</button></section><section class="card" style="margin-top:22px"><h2>Know your food data</h2><p>The catalog uses USDA SR Legacy, April 2018, plus selected manufacturer labels for paneer and dry soya. Tap each item for its source and preparation. Custom foods use your labels; recipe estimates use ingredient totals and cooked yield.</p><p>IFCT is the appropriate Indian composition reference; a verified IFCT import is still pending. This catalog does not claim FSSAI certification.</p><a href="https://www.nin.res.in/ebooks/IFCT2017.pdf" target="_blank" rel="noopener">View ICMR–NIN reference</a></section></div></div>`;$('#settings-form [name=goal]').value=state.profile.goal;$('#settings-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.profile.name=f.get('name').trim();state.profile.goal=f.get('goal');for(const k of Object.keys(state.profile.targets))state.profile.targets[k]=Number(f.get(k));persist();render();notify('Your goals are saved.');};$('#export').onclick=exportData;$('#manual-exercise').onclick=()=>checkin('exercise');$('#sync').onclick=sync;$('#restore').onclick=restore;if($('#signout'))$('#signout').onclick=async()=>{try{await authSession.signOut();cloudUser=null;clearTimeout(syncTimer);renderSettings();notify('Signed out. Your diary remains saved on this device.');}catch(e){notify(e.message);}};initSignIn();}
function prepareAuth(){
 const config=window.SPROUT_CONFIG?.firebase;
 if(!config?.apiKey||!config?.projectId)return;
 if(!authLoad)authLoad=createFirebaseSession(config,user=>{cloudUser=user;clearTimeout(syncTimer);if(tab==='settings')renderSettings();}).then(session=>{authSession=session;if(tab==='settings')renderSettings();return session;}).catch(()=>{authLoad=null;notify('Sign-in could not load. Check your connection and reload to retry.');});
 return authLoad;
}
function initSignIn(){
 const host=$('#google-signin');if(!host)return;
 if(!window.SPROUT_CONFIG?.firebase?.apiKey){host.innerHTML='<p class="hint">Firebase login is awaiting project configuration. Local tracking still works.</p>';return;}
 if(cloudUser){host.innerHTML=`<p>Signed in as ${esc(cloudUser.email)}. Cloud diary access is limited to the owner account.</p>`;return;}
 host.innerHTML=`<button class="secondary" id="firebase-login" ${authSession?'':'disabled'}>${authSession?'Continue with Google':'Loading sign-in…'}</button>`;
 $('#firebase-login').onclick=()=>{authSession.signIn().then(()=>notify('Signed in. Choose Sync or Restore to continue.')).catch(e=>notify(e.code==='auth/popup-blocked'?'Allow the sign-in popup, then try again.':e.code==='auth/unauthorized-domain'?'This website needs to be added to Firebase authorized domains.':e.code==='auth/popup-closed-by-user'?'Sign-in cancelled.':e.message));};
 prepareAuth();
}
async function api(path,options={}){if(!window.SPROUT_CONFIG?.apiUrl)throw Error('Cloud deployment is not configured yet. Your diary remains on this device.');if(!authSession)throw Error('Sign in before syncing your diary.');const bearer=await authSession.idToken();const res=await fetch(window.SPROUT_CONFIG.apiUrl+path,{...options,headers:{'Content-Type':'application/json',Authorization:'Bearer '+bearer,...options.headers}});const data=await res.json();if(!res.ok){if(data.acceptedRevision){state.revision=data.acceptedRevision;localStorage.setItem('sprout-v1',JSON.stringify(state));}throw Error(data.error||'Cloud request failed. Your local entries are safe.');}return data;}
async function sync(){if(!cloudUser||!window.SPROUT_CONFIG?.apiUrl||syncing)return;syncing=true;if($('#sync'))$('#sync').disabled=true;const eventId=state.eventId||crypto.randomUUID(),snapshot=structuredClone(Object.fromEntries(['version','days','customFoods','recipes','profile'].map(k=>[k,state[k]])));state.eventId=eventId;try{const data=await api('/sync',{method:'POST',body:JSON.stringify({eventId,baseRevision:state.revision,state:snapshot})});state.revision=data.revision;if(state.eventId===eventId)state.pending=false;localStorage.setItem('sprout-v1',JSON.stringify(state));updateStatus();notify('Diary saved to your cloud and BigQuery.');}catch(e){notify(e.message);}finally{syncing=false;if($('#sync'))$('#sync').disabled=!cloudUser;if(cloudUser&&state.eventId!==eventId&&state.pending){clearTimeout(syncTimer);syncTimer=setTimeout(sync,1200);}}}
async function restore(){if(!confirm('Replace this device’s diary with your cloud copy? Export local JSON first if you have unsynced entries.'))return;try{const data=await api('/state');if(!data.state)return notify('No cloud diary exists yet.');state={...data.state,revision:data.revision,pending:false};localStorage.setItem('sprout-v1',JSON.stringify(state));render();notify('Cloud diary restored.');}catch(e){notify(e.message);}}
try{const res=await fetch('foods.json');if(!res.ok)throw Error();foods=await res.json();}catch{notify('The food library could not load. Custom food entry is still available.');}
personal=personalCatalog(foods);
if(!state.profile.fuelContextVersion){if(state.profile.targets.kcal===2000&&state.profile.targets.protein===100){state.profile.targets.kcal=2100;state.profile.targets.protein=95;}state.profile.fuelContextVersion=1;persist();}
render();
prepareAuth();
if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'read_daily_fitness_summary',description:'Read the currently selected day’s logged nutrition, sleep, weight and exercise without changing it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected an empty object');return {date,...day(),totals:totals(day().meals),exerciseMinutes:exerciseMinutes(day())};}})).catch(()=>{});}

function attachDepth(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;document.querySelectorAll('.mission-scene,.combo-card,.visual-food-card').forEach(el=>{el.onpointermove=e=>{if(e.pointerType==='touch')return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.setProperty('--rx',(-y*5)+'deg');el.style.setProperty('--ry',(x*7)+'deg');};el.onpointerleave=()=>{el.style.setProperty('--rx','0deg');el.style.setProperty('--ry','0deg');};});}
function renderTraining(){const workouts=[{title:'Upper body',moves:'Band row · chest press around upper back · overhead press · curls',days:'MON / THU'},{title:'Lower body + core',moves:'Band squat · hip hinge · split squat · calf raise · dead bug',days:'TUE / FRI'}];$('#content').innerHTML=`<section class="training-intro"><span class="pill">BANDS · NO DOOR ANCHOR</span><h2>Stronger is a skill.<br>Practice it.</h2><p>A draft 12-week framework for your strength and gradual fat-loss goals. Start with the schedule you can recover from; four days is optional.</p><button class="primary" id="record-workout">Log today’s workout</button></section><div class="section-heading"><h2>Your weekly rhythm</h2><p>Recovery days between repeat muscle groups</p></div><div class="training-grid">${workouts.map(w=>`<section class="card"><span class="eyebrow">${w.days}</span><h2>${w.title}</h2><p>${w.moves}</p><p class="muted">Start with 2 sets per move, 8–15 controlled repetitions. Use a comfortable band and leave 2–3 good repetitions in reserve. Rest 60–120 seconds.</p></section>`).join('')}</div><div class="insight"><span>✦</span><div><b>Only 1–2 weeks in? Three days is plenty to start.</b><p>Use a full-body HASfit session on Monday, Wednesday and Friday if the split leaves you sore or fatigued. Walking or gentle mobility fits the other days. Inspect bands and follow their stretch limits; stop a movement that causes pain.</p></div></div><div class="section-heading"><h2>12 weeks, with room to adapt</h2></div><div class="phase-track">${[['01–04','Find your form','Repeat familiar sessions. Record the band used, repetitions and how hard it felt.'],['05–08','Build gradually','When all repetitions feel controlled, add reps or a little tension. Change one variable at a time.'],['09–12','Notice the change','Compare the same exercises and band setup. Review weekly weight averages, consistency and energy.']].map(([weeks,title,body])=>`<section class="card"><span class="eyebrow">WEEKS ${weeks}</span><h3>${title}</h3><p>${body}</p></section>`).join('')}</div><section class="card" style="margin-top:24px"><h2>Keep the coach you enjoy</h2><p>HASfit’s full-body band session describes using a long resistance band, with handles optional. Keep its easier modifications available.</p><a class="primary source-link" href="https://hasfit.com/workouts/home/strength-weight-training/full-body-resistance-band-workout/" target="_blank" rel="noopener">Open HASfit workout</a><p class="hint">This split is a draft, not a HASfit program. No minimum visible change in three months can be guaranteed. Your age, injury history, current measurements and exact band type are still unknown. <a href="https://www.cdc.gov/physical-activity-basics/guidelines/adults.html" target="_blank" rel="noopener">CDC activity guidance</a></p></section>`;$('#record-workout').onclick=()=>checkin('exercise');}
